INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-092',unit_id,'quiz-topic-neuro-ap1','Que osso forma a parede medial da fossa pterigopalatina?',NULL,'O corpo do esfenóide forma o teto; o limite posterior é constituído pela raiz da apófise pterigóide e pela face anterior adjacente da asa maior do esfenóide; o limite anterior corresponde à porção superomedial da face infratemporal, isto é, à face posterior da maxila. A lâmina perpendicular do <strong>osso palatino</strong>, com as apófises orbitária e esfenoidal, forma a parede medial, enquanto a fissura pterigomaxilar constitui o limite lateral. Na parede posterior abrem-se o buraco redondo, que transmite o nervo maxilar, e o canal pterigóideo, que transmite o nervo do canal pterigóideo; num esfenóide desarticulado, o buraco redondo situa-se superior e lateralmente ao canal pterigóideo.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 682–684.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
