INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-095-incorrect','quiz-neuro-ap1-095','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-096',unit_id,'quiz-topic-neuro-ap1','Qual das duas aberturas posteriores da fossa pterigopalatina é superior e lateral?',NULL,'Na parede posterior abrem-se o <strong>buraco redondo</strong>, que transmite o nervo maxilar, e o canal pterigóideo, que transmite o nervo do canal pterigóideo; num esfenóide desarticulado, o buraco redondo situa-se superior e lateralmente ao canal pterigóideo. A fossa comunica com a cavidade nasal através do buraco esfenopalatino; com a órbita pela extremidade medial da fissura orbitária inferior; e com a fossa infratemporal pela fissura pterigomaxilar, situada entre a face posterior da maxila e a apófise pterigóide do esfenóide.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 682–684.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-096-answer','quiz-neuro-ap1-096','Buraco redondo',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-096-incorrect','quiz-neuro-ap1-096','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-097',unit_id,'quiz-topic-neuro-ap1','Que nervo entra na fossa pterigopalatina pelo buraco redondo?',NULL,'O ramo meníngeo nasce ainda na fossa craniana média. O <strong>nervo maxilar</strong> abandona a cavidade craniana pelo buraco redondo e entra na porção superior da fossa pterigopalatina. Ao atravessar a fossa, origina dois grandes ramos ganglionares e dirige-se depois acentuadamente para lateral, sobre a apófise orbitária do palatino e a face posterior da maxila, alcançando a fissura orbitária inferior.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 683–684.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-097-answer','quiz-neuro-ap1-097','Nervo maxilar',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-097-incorrect','quiz-neuro-ap1-097','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-098',unit_id,'quiz-topic-neuro-ap1','Que nervo atravessa o canal pterigóideo?',NULL,'Na parede posterior abrem-se o buraco redondo, que transmite o nervo maxilar, e o canal pterigóideo, que transmite o <strong>nervo do canal pterigóideo</strong>; num esfenóide desarticulado, o buraco redondo situa-se superior e lateralmente ao canal pterigóideo. A fossa comunica com a cavidade nasal através do buraco esfenopalatino; com a órbita pela extremidade medial da fissura orbitária inferior; e com a fossa infratemporal pela fissura pterigomaxilar, situada entre a face posterior da maxila e a apófise pterigóide do esfenóide.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 682–684.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
