INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-098-incorrect','quiz-neuro-ap1-098','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-099',unit_id,'quiz-topic-neuro-ap1','Que abertura comunica a fossa pterigopalatina com a cavidade nasal?',NULL,'A fossa comunica com a cavidade nasal através do <strong>buraco esfenopalatino</strong>; com a órbita pela extremidade medial da fissura orbitária inferior; e com a fossa infratemporal pela fissura pterigomaxilar, situada entre a face posterior da maxila e a apófise pterigóide do esfenóide. Comunica ainda com a fossa craniana média pelo buraco redondo e pelo canal pterigóideo, e com a cavidade oral pelo canal palatino maior, que termina na região posterolateral do palato duro.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 682–684.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
