INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-102',unit_id,'quiz-topic-neuro-ap1','Que canal comunica a fossa pterigopalatina com a cavidade oral?',NULL,'A fossa comunica com a cavidade nasal através do buraco esfenopalatino; com a órbita pela extremidade medial da fissura orbitária inferior; e com a fossa infratemporal pela fissura pterigomaxilar, situada entre a face posterior da maxila e a apófise pterigóide do esfenóide. Comunica ainda com a fossa craniana média pelo buraco redondo e pelo canal pterigóideo, e com a cavidade oral pelo <strong>canal palatino maior</strong>, que termina na região posterolateral do palato duro. Esta rede de comunicações explica a continuidade anatómica entre base do crânio, órbita, fossas nasais, cavidade oral e fossa infratemporal.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 682–684.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-102-answer','quiz-neuro-ap1-102','Canal palatino maior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-102-incorrect','quiz-neuro-ap1-102','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-103',unit_id,'quiz-topic-neuro-ap1','Que porção da artéria maxilar ocupa a fossa pterigopalatina?',NULL,'Esta rede de comunicações explica a continuidade anatómica entre base do crânio, órbita, fossas nasais, cavidade oral e fossa infratemporal. Os principais conteúdos da fossa pterigopalatina são a <strong>terceira porção</strong> da artéria maxilar e os seus ramos, o nervo maxilar e numerosos ramos, e o gânglio pterigopalatino. A artéria maxilar entra na fossa através da fissura pterigomaxilar, onde termina como a sua terceira porção e origina múltiplos ramos destinados, entre outros territórios, à órbita, cavidade nasal e palato.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 682–684.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-103-answer','quiz-neuro-ap1-103','Terceira porção',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-103-incorrect','quiz-neuro-ap1-103','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-104',unit_id,'quiz-topic-neuro-ap1','Que gânglio se situa sob o nervo maxilar na fossa pterigopalatina?',NULL,'Esta passagem situa-se na região posterior da fossa e conduz fibras destinadas à mucosa da nasofaringe, posteriormente à tuba faringotimpânica. O <strong>gânglio pterigopalatino</strong> encontra-se profundamente protegido na fossa, imediatamente anterior ao canal pterigóideo, inferior e medialmente ao buraco redondo e ao nervo maxilar, e lateralmente ao buraco esfenopalatino. Situa-se, portanto, sob o nervo maxilar enquanto este atravessa a fossa.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 683–684.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-104-answer','quiz-neuro-ap1-104','Gânglio pterigopalatino',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-104-incorrect','quiz-neuro-ap1-104','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-105',unit_id,'quiz-topic-neuro-ap1','Qual é a modalidade funcional da divisão maxilar do trigémio?',NULL,'A divisão maxilar do nervo trigémio é <strong>exclusivamente sensitiva</strong> e origina grande parte dos seus ramos na fossa pterigopalatina. Entre os ramos nomeados encontram-se o meníngeo, os ramos ganglionares, o nervo zigomático, os nervos alveolares superiores e o nervo infraorbitário; através do gânglio pterigopalatino distribuem-se ainda ramos orbitários, nasopalatino, nasais posteriores superiores, palatinos e faríngeo.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 683–684.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-105-answer','quiz-neuro-ap1-105','Exclusivamente sensitiva',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-105-incorrect','quiz-neuro-ap1-105','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-106',unit_id,'quiz-topic-neuro-ap1','Em que nervo se continua anteriormente o nervo maxilar no canal infraorbitário?',NULL,'Ao atravessar a fossa, origina dois grandes ramos ganglionares e dirige-se depois acentuadamente para lateral, sobre a apófise orbitária do palatino e a face posterior da maxila, alcançando a fissura orbitária inferior. Mais anteriormente, muda de direção para entrar no canal infraorbitário, onde se continua como <strong>nervo infraorbitário</strong>. O ramo faríngeo associado ao nervo maxilar deixa o gânglio pterigopalatino posteriormente e entra no canal palatovaginal acompanhado pelo ramo faríngeo da artéria maxilar.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 683–684.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-106-answer','quiz-neuro-ap1-106','Nervo infraorbitário',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-106-incorrect','quiz-neuro-ap1-106','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-107',unit_id,'quiz-topic-neuro-ap1','Que canal conduz o ramo faríngeo do gânglio pterigopalatino?',NULL,'Mais anteriormente, muda de direção para entrar no canal infraorbitário, onde se continua como nervo infraorbitário. O ramo faríngeo associado ao nervo maxilar deixa o gânglio pterigopalatino posteriormente e entra no <strong>canal palatovaginal</strong> acompanhado pelo ramo faríngeo da artéria maxilar. Esta passagem situa-se na região posterior da fossa e conduz fibras destinadas à mucosa da nasofaringe, posteriormente à tuba faringotimpânica.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 683–684.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-107-answer','quiz-neuro-ap1-107','Canal palatovaginal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-107-incorrect','quiz-neuro-ap1-107','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-108',unit_id,'quiz-topic-neuro-ap1','Onde se situa o gânglio pterigopalatino relativamente ao buraco redondo?',NULL,'Esta passagem situa-se na região posterior da fossa e conduz fibras destinadas à mucosa da nasofaringe, posteriormente à tuba faringotimpânica. O gânglio pterigopalatino encontra-se profundamente protegido na fossa, imediatamente anterior ao canal pterigóideo, <strong>inferior e medialmente</strong> ao buraco redondo e ao nervo maxilar, e lateralmente ao buraco esfenopalatino. Situa-se, portanto, sob o nervo maxilar enquanto este atravessa a fossa.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, pp. 683–684.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
